// The Ember Dashboard's own admin token (EMBER_ADMIN_TOKEN_DASHBOARD, generated by `ember deploy`) opens the admin
// endpoints like EMBER_ADMIN_TOKEN; with neither set they are off.
import { env } from "cloudflare:test";
import { describe, expect, it } from "vitest";
import { createEmberWorker } from "../src/index.ts";
import { defineSchema } from "@freecorps/ember-server";

const worker = createEmberWorker({ schema: defineSchema({}), functions: {} });
const ctx = { waitUntil: () => {}, passThroughOnException: () => {}, props: {} } as unknown as ExecutionContext;
const call = (vars: Record<string, string>, token: string | null) =>
  worker.fetch(new Request("http://ember/api/_ember/capabilities", token ? { headers: { authorization: `Bearer ${token}` } } : {}), { ...env, EMBER_ADMIN_TOKEN: undefined, ...vars } as never, ctx);

describe("admin tokens", () => {
  it("either EMBER_ADMIN_TOKEN or EMBER_ADMIN_TOKEN_DASHBOARD opens the admin endpoints", async () => {
    expect((await call({}, "x")).status).toBe(403);
    expect((await call({ EMBER_ADMIN_TOKEN_DASHBOARD: "dash" }, "dash")).status).toBe(200);
    expect((await call({ EMBER_ADMIN_TOKEN_DASHBOARD: "dash" }, "nope")).status).toBe(401);
    expect((await call({ EMBER_ADMIN_TOKEN_DASHBOARD: "dash" }, null)).status).toBe(401);
    expect((await call({ EMBER_ADMIN_TOKEN: "ops", EMBER_ADMIN_TOKEN_DASHBOARD: "dash" }, "ops")).status).toBe(200);
    expect((await call({ EMBER_ADMIN_TOKEN: "ops", EMBER_ADMIN_TOKEN_DASHBOARD: "dash" }, "dash")).status).toBe(200);
    expect((await call({ EMBER_ADMIN_TOKEN: "ops", EMBER_ADMIN_TOKEN_DASHBOARD: "" }, "")).status).toBe(401);
  });
});
